ncipal versus agent"}, {"id": "5d5d296e-2701-4180-b070-2414688ddba5", "type": "concept", "title": "Licenses, warranties, returns, and significant financing components"}], "description": "This subtopic focuses on contract features that make revenue recognition difficult in practice."}, {"id": "76d8ae21-239b-46d7-aacd-4e7fd9c3ebcf", "type": "subtopic", "title": "Contract balances and disclosures", "children": [{"id": "3036b25a-a83a-46d5-a8e8-aaae32a42603", "type": "concept", "title": "Contract assets and liabilities"}, {"id": "b4d0ef3f-d0eb-4c71-b402-cb8ad2bf2ecf", "type": "concept", "title": "Deferred revenue and remaining performance obligations"}, {"id": "e60220b6-cd8b-4c6b-9979-cf9bb02b1dd9", "type": "concept", "title": "Disaggregation and policy disclosures"}], "description": "Students learn how revenue judgments appear in balance sheet accounts and footnotes."}]}, {"id": "702007c1-1da8-4d8d-b75e-aa507f1a7b0c", "type": "topic", "title": "Accounting for income taxes", "description": "Recognize current and deferred taxes, valuation allowances, uncertain tax positions, and rate reconciliations.", "children": [{"id": "a46bac6c-522e-4202-b902-6734f066869d", "type": "subtopic", "title": "Current and deferred tax model", "children": [{"id": "f33ef143-f8fa-408a-89af-bd26b24734e0", "type": "concept", "title": "Temporary versus permanent differences"}, {"id": "69b719e0-6905-43e8-b7e9-79ab6f5544f2", "type": "concept", "title": "Deferred tax assets and liabilities"}, {"id": "e3067a6d-dce4-4802-a993-67fca46fe18c", "type": "concept", "title": "Enacted tax rates and measurement"}], "description": "Students learn why book income and taxable income differ and how those differences become tax assets/liabilities."}, {"id": "165cb564-8737-4b6b-928c-7e9436da24d3", "type": "subtopic", "title": "Valuation allowances and uncertainty", "children": [{"id": "2b8eed65-2c9f-4e8c-984c-af9d016a7685", "type": "concept", "title": "More-likely-than-not threshold"}, {"id": "3e46ca8e-ac61-4322-a8a7